internal static class NativeObjects {
 private static readonly List<WeakReference<Legacy.Object>> Objects=new();internal static readonly Dictionary<int,HideFlags> Flags=new();
 internal static void Track(Legacy.Object obj){if(obj is Legacy.Component or Legacy.GameObject)return;if(Objects.Count>=65536)Objects.RemoveAll(value=>!value.TryGetTarget(out _));Objects.Add(new(obj));}
 internal static Object[] Alive(Type type)=>Objects.Select(reference=>reference.TryGetTarget(out var value)?value:null).Where(value=>value&&type.IsInstanceOfType(Object.Wrap(value!))).Select(value=>Object.Wrap(value!)).DistinctBy(value=>value.GetInstanceID()).ToArray();
 internal static Object[] All(Type type){ArgumentNullException.ThrowIfNull(type);if(!typeof(Object).IsAssignableFrom(type))throw new ArgumentException("An Object type is required");return Legacy.Object.FindObjectsByType(type,Legacy.FindObjectsInactive.Include,Legacy.FindObjectsSortMode.None).Select(Object.Wrap).Concat(Alive(type)).DistinctBy(value=>value.GetInstanceID()).ToArray();}
 internal static Legacy.GameObject GameObject(int id){foreach(var (key,value) in Legacy.Context.ObjectIdentities)if(value==id&&key.Slot=="gameObject"&&key.Entity.Generation==Legacy.Context.Generation&&Legacy.Context.Entities.ContainsKey(key.Entity.Id)&&key.Epoch==Legacy.Context.ObjectEpochs.GetValueOrDefault((key.Entity,key.Slot)))return new Legacy.GameObject(key.Entity);throw new ArgumentException("Instance ID does not identify a live GameObject");}
}
