public partial class GameObject {
 public TransformHandle transformHandle=>new(transform);
 // Native child traversal is relative to the query root: its inactive ancestors do not hide activeSelf descendants.
 // Parent traversal instead filters every candidate by activeInHierarchy, including the receiver itself.
 private Legacy.Component[] QueryHierarchy(Type type,bool parents,bool includeInactive){
  var owner=LegacyGameObject;Legacy.ObjectQueries.ComponentType(QueryType(type));var result=new List<Legacy.Component>();
  if(parents){for(Legacy.Transform? node=owner.transform;node!=null;node=node.parent)if(includeInactive||node.gameObject.activeInHierarchy)result.AddRange(node.gameObject.GetComponents(type));}
  else{void Visit(Legacy.Transform node,bool self){if(!self&&!includeInactive&&!node.gameObject.activeSelf)return;result.AddRange(node.gameObject.GetComponents(type));for(var i=0;i<node.childCount;i++)Visit(node.GetChild(i),false);}Visit(owner.transform,true);}
  return result.ToArray();
 }
 public Component? GetComponentInChildren(Type type)=>GetComponentInChildren(type,false);public Component? GetComponentInChildren(Type type,bool includeInactive)=>GetComponentsInChildren(type,includeInactive).FirstOrDefault();public Component? GetComponentInParent(Type type)=>GetComponentInParent(type,false);public Component? GetComponentInParent(Type type,bool includeInactive)=>GetComponentsInParent(type,includeInactive).FirstOrDefault();
 public Component[] GetComponentsInChildren(Type type)=>GetComponentsInChildren(type,false);public Component[] GetComponentsInChildren(Type type,bool includeInactive)=>QueryHierarchy(type,false,includeInactive).Select(native=>(Component)Object.Wrap(native)).ToArray();public Component[] GetComponentsInParent(Type type)=>GetComponentsInParent(type,false);public Component[] GetComponentsInParent(Type type,bool includeInactive)=>QueryHierarchy(type,true,includeInactive).Select(native=>(Component)Object.Wrap(native)).ToArray();
 public void GetComponents(Type type,List<Component> results){if(results==null){_=transform;return;}var values=GetComponents(type);results.Clear();results.AddRange(values);}
 public void GetComponentsInChildren<T>(List<T> results)=>GetComponentsInChildren(false,results);public void GetComponentsInChildren<T>(bool includeInactive,List<T> results){_=LegacyGameObject;if(results!=null){var values=GetComponentsInChildren<T>(includeInactive);results.Clear();results.AddRange(values);}}public void GetComponentsInParent<T>(bool includeInactive,List<T> results){_=LegacyGameObject;if(results!=null){var values=GetComponentsInParent<T>(includeInactive);results.Clear();results.AddRange(values);}}
